using System.Text;

namespace ZeeCore.Generator;

/// Emits `zee_contracts.h`: the schema and engine contract fingerprints and
/// every root's wire tags for C and C++ callers of `zee_app.h` and
/// `zee_engine.h`.
internal static class CHeaderEmitter {
    #region Actions - Emitting

    public static string Emit(ContractSchema schema) {
        ArgumentNullException.ThrowIfNull(schema);
        var code = new StringBuilder();
        code.Append("""
            /* <auto-generated/>
             * Generated by ZeeCore/tools/ZeeCore.Generator from the C# contract records. Do not edit.
             * A union on the wire is its root's tag (a LEB128 varint) followed by the type's fields.
             */
            #ifndef ZEE_CONTRACTS_H
            #define ZEE_CONTRACTS_H

            /* SHA-256 of the canonical contract schema; pass it to zee_app_create. */
            #define ZEE_CONTRACTS_FINGERPRINT_LENGTH 32u

            """);
        code.Append("#define ZEE_CONTRACTS_FINGERPRINT { ");
        code.Append(string.Join(", ", schema.Fingerprint.Select(value => $"0x{value:x2}"))).Append(" }\n");
        code.Append("""

            /* SHA-256 of the engine contract alone; pass it to zee_engine_register. */
            #define ZEE_ENGINE_CONTRACT_FINGERPRINT_LENGTH 32u

            """);
        code.Append("#define ZEE_ENGINE_CONTRACT_FINGERPRINT { ");
        code.Append(string.Join(", ", schema.EngineFingerprint.Select(value => $"0x{value:x2}"))).Append(" }\n");
        foreach (var root in ContractRoot.All.Where(root => root.ReachesCore)) {
            code.Append('\n').Append($"/* {root} tags */\n");
            string prefix = $"ZEE_{Naming.UpperSnake(root.Name)}_";
            foreach (var member in schema.Members(root))
                code.Append($"#define {prefix}{Naming.UpperSnake(member.Name)} {member.Tag}u\n");
        }
        code.Append("\n#endif /* ZEE_CONTRACTS_H */\n");
        return code.ToString();
    }

    #endregion
}
